import sys
sys.setrecursionlimit(200000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    if N == 1:
        print(0)
        return

    adj = [[] for _ in range(N + 1)]

    for _ in range(N - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    selected = [False] * (N + 1)
    count = 0

    def dfs(u, p):
        nonlocal count
        is_leaf = True
        for v in adj[u]:
            if v != p:
                is_leaf = False
                dfs(v, u)

        if is_leaf:
            return

        needs_selection = False
        for v in adj[u]:
            if v != p: selected[v]
            else:
                pass

        for v in adj[u]:
            if v != p and not selected[v]:
                needs_selection = True
                break

        if needs_selection:
            selected[u] = True
            count += 1

    dfs(1, 0)

    has_uncovered_edge = False
    for i in range(1, N + 1):
        if not selected[i]:
            for v in adj[i]:
                if not selected[v]:
                    has_uncovered_edge = True
                    break
        if has_uncovered_edge:
            break

    if has_uncovered_edge:
        count += 1

    print(count)

if __name__ == "__main__":
    main()
